# --- index.html: hero quote, story, values-detail ---
add(
  "Nie pytam: <span>„Co jest z Tobą nie tak?”</span>\n        Wolę zapytać: <em>„Co Ci się przydarzyło?”</em>",
  "I don't ask: <span>“What's wrong with you?”</span>\n        I'd rather ask: <em>“What happened to you?”</em>",
  "Я не питаю: <span>«Що з тобою не так?»</span>\n        Я радше запитаю: <em>«Що з тобою сталося?»</em>",
  "Ich frage nicht: <span>„Was stimmt nicht mit dir?“</span>\n        Ich frage lieber: <em>„Was ist dir widerfahren?“</em>",
)
add(
  "Bo czasem nie potrzebujesz rady. Potrzebujesz kogoś, kto pomoże Ci uwierzyć,\n        że to jeszcze nie koniec Twojej historii.",
  "Because sometimes you don't need advice. You need someone to help you believe\n        that this isn't the end of your story.",
  "Бо іноді тобі не потрібна порада. Тобі потрібен той, хто допоможе повірити,\n        що це ще не кінець твоєї історії.",
  "Denn manchmal brauchst du keinen Rat. Du brauchst jemanden, der dir hilft zu glauben,\n        dass dies noch nicht das Ende deiner Geschichte ist.",
)
add("Nie musisz przechodzić przez to sam.", "You don't have to go through this alone.", "Тобі не потрібно проходити через це самотужки.", "Du musst das nicht allein durchstehen.")
add("Akceptacja, szacunek i zrozumienie.", "Acceptance, respect and understanding.", "Прийняття, повага та розуміння.", "Akzeptanz, Respekt und Verständnis.")
add("Twoja historia pozostaje między nami.", "Your story stays between us.", "Твоя історія залишається між нами.", "Deine Geschichte bleibt unter uns.")
add("Czasem to właśnie bywa pierwszym krokiem do ulgi.", "Sometimes that's the very first step toward relief.", "Іноді саме це стає першим кроком до полегшення.", "Manchmal ist genau das der erste Schritt zur Erleichterung.")
add("Razem poszukamy kierunku zgodnego z Tobą.", "Together we'll look for a direction that's right for you.", "Разом ми знайдемо напрямок, що підходить саме тобі.", "Gemeinsam suchen wir nach einer Richtung, die zu dir passt.")
add("Zatrzymaj się na chwilę...", "Pause for a moment...", "Зупинись на мить...", "Halte einen Moment inne...")
add("Być może od wielu dni nosisz w sobie ból, którego nie potrafisz już nikomu opowiedzieć.", "Perhaps for many days now you've been carrying a pain you can no longer put into words for anyone.", "Можливо, ти вже багато днів носиш у собі біль, про який більше не можеш нікому розповісти.", "Vielleicht trägst du seit vielen Tagen einen Schmerz in dir, den du niemandem mehr erzählen kannst.")
add("Może ktoś odszedł. Może ktoś Cię zawiódł. Może straciłeś wiarę w siebie. A może po prostu jesteś zmęczony udawaniem, że wszystko jest dobrze.", "Maybe someone left. Maybe someone let you down. Maybe you've lost faith in yourself. Or maybe you're simply tired of pretending everything is fine.", "Можливо, хтось пішов. Можливо, хтось тебе підвів. Можливо, ти втратив віру в себе. А можливо, ти просто втомився вдавати, що все добре.", "Vielleicht ist jemand gegangen. Vielleicht hat dich jemand enttäuscht. Vielleicht hast du den Glauben an dich selbst verloren. Oder du bist einfach müde, so zu tun, als wäre alles gut.")
add("Dokładniej — jestem tu dla kobiet i mężczyzn, którzy:", "More specifically — I'm here for women and men who:", "Точніше — я тут для жінок і чоловіків, які:", "Genauer gesagt — ich bin hier für Frauen und Männer, die:")
add("Jestem psychologiem i ukończyłam jednolite studia magisterskie z psychologii. W swojej pracy kieruję się szacunkiem, empatią oraz przekonaniem, że każdy człowiek ma prawo do wysłuchania i profesjonalnego wsparcia.", "I am a psychologist with a master's degree in psychology. In my work I'm guided by respect, empathy, and the conviction that every person has the right to be heard and to receive professional support.", "Я психолог, маю повну магістерську освіту з психології. У своїй роботі керуюся повагою, емпатією та переконанням, що кожна людина має право бути вислуханою та отримати професійну підтримку.", "Ich bin Psychologin mit einem Masterabschluss in Psychologie. In meiner Arbeit leiten mich Respekt, Empathie und die Überzeugung, dass jeder Mensch ein Recht auf Gehör und professionelle Unterstützung hat.")
add("Tworzę miejsce, w którym możesz mówić o swoich emocjach bez lęku przed oceną. Łączę wiedzę psychologiczną, etykę zawodową i pokorę wobec ludzkiego cierpienia.", "I create a place where you can talk about your emotions without fear of judgment. I combine psychological knowledge, professional ethics, and humility toward human suffering.", "Я створюю простір, де ти можеш говорити про свої емоції без страху осуду. Я поєдную психологічні знання, професійну етику та смирення перед людським стражданням.", "Ich schaffe einen Ort, an dem du über deine Gefühle sprechen kannst, ohne Angst vor Bewertung. Ich verbinde psychologisches Wissen, Berufsethik und Demut gegenüber menschlichem Leid.")
add("Twoja historia ma znaczenie.", "Your story matters.", "Твоя історія має значення.", "Deine Geschichte zählt.")
add("Bezpieczna rozmowa, rozpoznanie potrzeb i wspólne ustalenie dalszego kierunku.", "A safe conversation, identifying your needs, and jointly deciding on the way forward.", "Безпечна розмова, визначення потреб і спільне окреслення подальшого напрямку.", "Ein sicheres Gespräch, das Erkennen von Bedürfnissen und die gemeinsame Festlegung der weiteren Richtung.")
add("Pomoc w trudnych wydarzeniach życiowych, nagłych zmianach i kryzysie zdrowotnym.", "Help with difficult life events, sudden changes, and health crises.", "Допомога у складних життєвих подіях, раптових змінах та кризах здоров'я.", "Hilfe bei schwierigen Lebensereignissen, plötzlichen Veränderungen und gesundheitlichen Krisen.")
add("Wsparcie w przeżywaniu straty, złości, lęku i poczucia odrzucenia.", "Support in coping with loss, anger, anxiety, and feelings of rejection.", "Підтримка у переживанні втрати, гніву, тривоги та відчуття відторгнення.", "Unterstützung bei der Verarbeitung von Verlust, Wut, Angst und Ablehnungsgefühlen.")
add("Praca nad zaufaniem do siebie, granicami i odzyskaniem wewnętrznej równowagi.", "Working on self-trust, boundaries, and regaining inner balance.", "Робота над довірою до себе, межами та відновленням внутрішньої рівноваги.", "Arbeit an Selbstvertrauen, Grenzen und der Wiedererlangung des inneren Gleichgewichts.")
add("Kryzys życiowy", "Life crisis", "Життєва криза", "Lebenskrise")
add("Relacje", "Relationships", "Стосунки", "Beziehungen")
add("Poczucie własnej wartości", "Self-worth", "Почуття власної гідності", "Selbstwertgefühl")
add("Pierwszy krok nie musi być wielki. Wystarczy jedna chwila odwagi, aby umówić konsultację.", "The first step doesn't have to be big. It only takes one moment of courage to book a consultation.", "Перший крок не мусить бути великим. Достатньо однієї миті сміливості, щоб записатися на консультацію.", "Der erste Schritt muss nicht groß sein. Ein Moment des Mutes genügt, um eine Beratung zu buchen.")
add("ul. Słowackiego 24/19, Rzeszów, Polska", "ul. Słowackiego 24/19, Rzeszów, Poland", "ul. Słowackiego 24/19, Жешув, Польща", "ul. Słowackiego 24/19, Rzeszów, Polen")
add("Nie musisz być silny przez cały czas. Tutaj nie musisz niczego udowadniać.", "You don't have to be strong all the time. Here, you don't have to prove anything.", "Тобі не потрібно бути сильним постійно. Тут тобі не потрібно нічого доводити.", "Du musst nicht die ganze Zeit stark sein. Hier musst du nichts beweisen.")
add("„Nie obiecuję, że od jutra wszystko będzie łatwe. Obiecuję bezpieczną przestrzeń, profesjonalne wsparcie i pełną obecność.”", "“I don't promise that everything will be easy from tomorrow. I promise a safe space, professional support, and my full presence.”", "«Я не обіцяю, що з завтрашнього дня все стане легко. Я обіцяю безпечний простір, професійну підтримку та повну присутність».", "„Ich verspreche nicht, dass ab morgen alles leicht wird. Ich verspreche einen sicheren Raum, professionelle Unterstützung und meine volle Präsenz.“")

